"""Shared CUDA sampling variant configuration.

The dispatch path and cubin bundle precompiler both consume this module so
supported vocab sizes, thread counts, and variant keys stay in sync.
"""

from __future__ import annotations

from dataclasses import dataclass

MAX_REJECTION_ROUNDS = 16
SOFTMAX_GREEDY_LOGITS_DTYPES = ("float32", "bfloat16")
CONSTRAINT_PLAN_WIDTH = 8
LOGITS_CONSTRAINT_CONFIGS = {51866: 512}
GREEDY_LOGPROBS_CONFIGS = {(51866, "bfloat16"): 512}
CONSTRAINED_ARGMAX_CONFIGS = {51866: 512}
# Portable functional baseline: the kernel's existing default launch. Tuned
# target configurations remain separate and require their generated evidence.
PORTABLE_GREEDY_TAIL_THREADS = 256
PORTABLE_GREEDY_TAIL_SPLITS = 32


@dataclass(frozen=True)
class SamplingVocabConfig:
    vocab_size: int
    sampling_threads: int
    softmax_greedy_threads: int


SAMPLING_VOCAB_CONFIGS = (
    SamplingVocabConfig(
        vocab_size=1024,
        sampling_threads=128,
        softmax_greedy_threads=128,
    ),
    # Tried 128/256 threads: 1.22/1.18x and 1.20/1.20x the 512-thread
    # H100/B200 latency; keeping 512.
    SamplingVocabConfig(
        vocab_size=3072,
        sampling_threads=512,
        softmax_greedy_threads=512,
    ),
    SamplingVocabConfig(
        vocab_size=51200,
        sampling_threads=768,
        softmax_greedy_threads=256,
    ),
    SamplingVocabConfig(
        vocab_size=51866,
        sampling_threads=768,
        softmax_greedy_threads=512,
    ),
    SamplingVocabConfig(
        vocab_size=248320,
        sampling_threads=1024,
        softmax_greedy_threads=1024,
    ),
    SamplingVocabConfig(
        vocab_size=262144,
        sampling_threads=1024,
        softmax_greedy_threads=1024,
    ),
)

SUPPORTED_VOCAB_SIZES = frozenset(c.vocab_size for c in SAMPLING_VOCAB_CONFIGS)
SAMPLING_THREADS = {c.vocab_size: c.sampling_threads for c in SAMPLING_VOCAB_CONFIGS}
SOFTMAX_GREEDY_THREADS = {
    c.vocab_size: c.softmax_greedy_threads for c in SAMPLING_VOCAB_CONFIGS
}
TOKEN_MASK_REPETITION_CONFIGS = {3072: SOFTMAX_GREEDY_THREADS[3072]}


def sampling_variant_key(vocab_size: int) -> str:
    return f"vocab_{vocab_size}"


def softmax_greedy_variant_key(vocab_size: int, logits_dtype: str) -> str:
    if logits_dtype == "bfloat16":
        return f"vocab_{vocab_size}_bf16"
    if logits_dtype != "float32":
        raise ValueError(f"unsupported softmax_greedy logits dtype: {logits_dtype!r}")
    return f"vocab_{vocab_size}"


def portable_greedy_tail_variant_key(vocab_size: int) -> str:
    return f"vocab_{vocab_size}_bf16_greedy_tail_portable"


def logits_constraints_variant_key(vocab_size: int) -> str:
    return f"vocab_{vocab_size}_bf16_constraints3_inplace"


def token_mask_repetition_variant_key(vocab_size: int) -> str:
    return f"vocab_{vocab_size}_bf16_token_mask_repetition"


def greedy_logprobs_variant_key(vocab_size: int, logits_dtype: str) -> str:
    if logits_dtype not in SOFTMAX_GREEDY_LOGITS_DTYPES:
        raise ValueError(f"unsupported greedy-logprobs dtype: {logits_dtype!r}")
    return f"vocab_{vocab_size}_{logits_dtype}_greedy_logprobs"


def constrained_argmax_variant_key(vocab_size: int) -> str:
    return f"vocab_{vocab_size}_bf16_constraints3"
